from ...config import ENBConfig

from .base_cl_tool import BaseClToolInterface


class NtpInterface(BaseClToolInterface):
    """Keywords for NTP related commands."""

    def change_ntp_server_ip_address(self, ntpserver, timeout='5min', **kwargs):
        """Changes NTP server IP address(es).

        :param string/list ntpserver: new NTP server IP address(es) to be used e.g. 1.1.1.1 or 1.1.1.1,2.2.2.2
        :param string ne: If None, BTSSM scans for eNB TRS IP
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        ntpserver = ','.join(ntpserver) if type(ntpserver) is list else ntpserver.strip()
        params = {'ne': ne, 'pw': pw, 'ntpservers': ntpserver, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='changentp', params=params, trs_ip=ne, flags=flags)
